<h1 class="h3 mb-4"><?= $channel ? 'Editar canal' : 'Novo canal' ?></h1><form method="post" action="/canais/salvar" class="card card-body bg-white"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><?php if ($channel): ?><input type="hidden" name="id" value="<?= (int) $channel['id'] ?>"><?php endif; ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Nome</label><input class="form-control" name="nome" maxlength="150" required value="<?= htmlspecialchars($channel['nome'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-6"><label class="form-label">Plataforma</label><select class="form-select" name="plataforma_id" required><?php foreach ($platforms as $platform): ?><option value="<?= (int) $platform['id'] ?>" <?= (($channel['plataforma_id'] ?? null) == $platform['id']) ? 'selected' : '' ?>><?= htmlspecialchars($platform['nome'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Identificador externo</label><input class="form-control" name="identificador_externo" maxlength="190" value="<?= htmlspecialchars($channel['identificador_externo'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-6"><label class="form-label">Fuso horário</label><input class="form-control" name="fuso_horario" value="<?= htmlspecialchars($channel['fuso_horario'] ?? 'America/Sao_Paulo', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-12"><label><input type="checkbox" name="ativo" <?= (!$channel || $channel['ativo']) ? 'checked' : '' ?>> Ativo</label></div></div><div class="mt-4"><button class="btn btn-primary">Salvar</button> <a class="btn btn-outline-secondary" href="/canais">Cancelar</a></div></form>
